package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a claim hold toggle by a user who may not change the sheet. */
public class ValidateHoldClaim {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody HoldClaimRequest request,
            Out<HoldClaimInput> body, RoleStore roles) throws InvalidSheetException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheetId.trim(), user);
        body.set(new HoldClaimInput(user));
    }
}
package net.officefloor.hq.app.claim;

/** Body of a claim's hold toggle, as sent: who holds or releases it. */
public record HoldClaimRequest(String user) {
}
package net.officefloor.hq.app.claim;

/** A validated claim hold toggle: the user who holds or releases it. */
public record HoldClaimInput(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses holding or releasing a claim that is not OPEN or PENDING. */
public class CheckHoldClaim {
    public void check(@Val Claim claim) throws InvalidSheetException {
        if (!claim.getStatus().isOpen()) {
            throw new InvalidSheetException("Only an OPEN or PENDING claim can be held or released");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Stores the claim held, or released when it was held; refused when another user moved it on or toggled it first. */
public class ApplyHoldClaim {
    public void apply(@Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (!store.toggleHeld(claim)) {
            throw new InvalidSheetException("Only an OPEN or PENDING claim can be held or released");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
