package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSplit {
    /** A number with up to two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SplitRequest request, Out<SplitInput> body,
            RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number with up to two decimals");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() <= 0) {
            throw new InvalidSheetException("The amount split off must be more than 0.00");
        }
        body.set(new SplitInput(value, request.user()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Refuses splitting a claim that is not OPEN (a PENDING one too), one deferred on the sheet's today, an
 *  amount not less than the claim's, or a split by a role the sheet's permission matrix does not allow to
 *  open a claim (the new claim is theirs to open). */
public class CheckSplit {
    public void check(@Val SplitInput input, @Val Claim claim, RoleStore roles, SettingStore settings, SheetStore sheets)
            throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new InvalidSheetException("Only an OPEN claim can be split");
        }
        if (claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new InvalidSheetException("A deferred claim cannot be split until " + claim.getDeferredUntil());
        }
        if (input.amount().compareTo(claim.getAmount()) >= 0) {
            throw new InvalidSheetException("The amount split off must be less than the claim's " + claim.getAmount());
        }
        CheckClerkLimit.refuseUnpermitted(ClaimStatus.OPEN, claim.getSheetId(),
                roles.find(claim.getSheetId(), input.user()), settings);
    }
}
# POST /api/sheets/{sheetId}/claims/{claimId}/split — split an amount (body {amount, user}), more than
# 0.00 and less than the claim's amount, off an OPEN claim. The claim keeps the rest of its amount and is
# unbound from any figure a statement bound it to; a new OPEN claim with the amount split off, the same
# date and note, the next number, opened by the user, split-from the claim's number and due by its date
# plus the terms in force on that date (fixed now) is listed as its person's newest claim. Refused (400)
# when the amount does not parse or is out of range, the claim is not OPEN (PENDING, deferred on the
# sheet's today, settled, ...) or not on the sheet, its due-by falls in a closed period, or the sheet's
# permission matrix does not allow the user's role to open a claim; nothing is stored then. A stored
# split is recorded in the audit file as CLAIM_SPLIT, then CLAIM_OPENED for the new claim.
validate:
  class: net.officefloor.hq.app.claim.ValidateSplit
  next: load

